64	// shadowBranchPattern matches shadow branch names in both old and new formats:
65	//   - Old format: entire/<commit[:7+]>
66	//   - New format: entire/<commit[:7+]>-<worktreeHash[:6]>
67	//
68	// The pattern requires at least 7 hex characters for the commit, optionally followed
69	// by a dash and exactly 6 hex characters for the worktree hash.
70	var shadowBranchPattern = regexp.MustCompile(`^entire/[0-9a-fA-F]{7,}(-[0-9a-fA-F]{6})?$`)
71	
72	// IsShadowBranch returns true if the branch name matches the shadow branch pattern.
73	// Shadow branches have the format "entire/<commit-hash>-<worktree-hash>" where the
74	// commit hash is at least 7 hex characters and worktree hash is 6 hex characters.
75	// The "entire/checkpoints/v1" branch is NOT a shadow branch.
76	func IsShadowBranch(branchName string) bool {
77		// Explicitly exclude metadata and trails branches
78		if branchName == paths.MetadataBranchName || branchName == paths.TrailsBranchName {
79			return false
80		}
81		return shadowBranchPattern.MatchString(branchName)
82	}
83	
84	// ListShadowBranches returns all shadow branches in the repository.
85	// Shadow branches match the pattern "entire/<commit-hash>" (7+ hex chars).
86	// The "entire/checkpoints/v1" branch is excluded as it stores permanent metadata.
87	// Returns an empty slice (not nil) if no shadow branches exist.
88	func ListShadowBranches(ctx context.Context) ([]string, error) {
89		repo, err := OpenRepository(ctx)
90		if err != nil {
91			return nil, fmt.Errorf("failed to open git repository: %w", err)
92		}
93	
94		refs, err := repo.References()
95		if err != nil {
96			return nil, fmt.Errorf("failed to get references: %w", err)
97		}
98	
99		var shadowBranches []string
100	
101		err = refs.ForEach(func(ref *plumbing.Reference) error {
102			if err := ctx.Err(); err != nil {
103				return err //nolint:wrapcheck // Propagating context cancellation
104			}
105			// Only look at branch references
106			if !ref.Name().IsBranch() {
107				return nil
108			}
109	
110			// Extract branch name without refs/heads/ prefix
111			branchName := strings.TrimPrefix(ref.Name().String(), "refs/heads/")
112	
113			if IsShadowBranch(branchName) {
114				shadowBranches = append(shadowBranches, branchName)
115			}
116			return nil
117		})
118		if err != nil {
119			return nil, fmt.Errorf("failed to iterate references: %w", err)
120		}
121	
122		// Ensure we return empty slice, not nil
123		if shadowBranches == nil {
124			shadowBranches = []string{}
125		}
126	
127		return shadowBranches, nil
128	}
