130	// DeleteShadowBranches deletes the specified branches from the repository.
131	// Returns two slices: successfully deleted branches and branches that failed to delete.
132	// Individual branch deletion failures do not stop the operation - all branches are attempted.
133	func DeleteShadowBranches(ctx context.Context, branches []string) (deleted []string, failed []string, err error) { //nolint:unparam // already present in codebase
134		if len(branches) == 0 {
135			return []string{}, []string{}, nil
136		}
137	
138		for _, branch := range branches {
139			// Use git CLI to delete branches because go-git v5's RemoveReference
140			// doesn't properly persist deletions with packed refs or worktrees
141			if err := DeleteBranchCLI(ctx, branch); err != nil {
142				failed = append(failed, branch)
143				continue
144			}
145	
146			deleted = append(deleted, branch)
147		}
148	
149		return deleted, failed, nil
150	}
