152	// ListOrphanedSessionStates returns session state files that are orphaned.
153	// A session state is orphaned if:
154	//   - No checkpoints on entire/checkpoints/v1 reference this session ID
155	//   - No shadow branch exists for the session's base commit
156	//
157	// This is strategy-agnostic as session states are shared by all strategies.
158	func ListOrphanedSessionStates(ctx context.Context) ([]CleanupItem, error) {
159		repo, err := OpenRepository(ctx)
160		if err != nil {
161			return nil, fmt.Errorf("failed to open git repository: %w", err)
162		}
163	
164		// Get all session states
165		store, err := session.NewStateStore(ctx)
166		if err != nil {
167			return nil, fmt.Errorf("failed to create state store: %w", err)
168		}
169	
170		states, err := store.List(ctx)
171		if err != nil {
172			return nil, fmt.Errorf("failed to list session states: %w", err)
173		}
174	
175		if len(states) == 0 {
176			return []CleanupItem{}, nil
177		}
178	
179		// Get all checkpoints to find which sessions have checkpoints
180		cpStore := checkpoint.NewGitStore(repo)
181	
182		sessionsWithCheckpoints := make(map[string]bool)
183		checkpoints, listErr := cpStore.ListCommitted(ctx)
184		if listErr == nil {
185			for _, cp := range checkpoints {
186				sessionsWithCheckpoints[cp.SessionID] = true
187			}
188		}
189	
190		// Get all shadow branches as a set for quick lookup
191		shadowBranches, _ := ListShadowBranches(ctx) //nolint:errcheck // Best effort
192		shadowBranchSet := make(map[string]bool)
193		for _, branch := range shadowBranches {
194			shadowBranchSet[branch] = true
195		}
196	
197		var orphaned []CleanupItem
198		now := time.Now()
199	
200		for _, state := range states {
201			// Skip sessions that started recently - they may be actively in use
202			// but haven't created their first checkpoint yet
203			if now.Sub(state.StartedAt) < sessionGracePeriod {
204				continue
205			}
206	
207			// Check if session has checkpoints on entire/checkpoints/v1
208			hasCheckpoints := sessionsWithCheckpoints[state.SessionID]
209	
210			// Check if shadow branch exists for this session's base commit and worktree
211			// Shadow branches are now worktree-specific: entire/<commit[:7]>-<worktreeHash[:6]>
212			expectedBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
213			hasShadowBranch := shadowBranchSet[expectedBranch]
214	
215			// Session is orphaned if it has no checkpoints AND no shadow branch
216			if !hasCheckpoints && !hasShadowBranch {
217				reason := "no checkpoints or shadow branch found"
218				orphaned = append(orphaned, CleanupItem{
219					Type:   CleanupTypeSessionState,
220					ID:     state.SessionID,
221					Reason: reason,
222				})
223			}
224		}
225	
226		return orphaned, nil
227	}
