229	// DeleteOrphanedSessionStates deletes the specified session state files.
230	func DeleteOrphanedSessionStates(ctx context.Context, sessionIDs []string) (deleted []string, failed []string, err error) {
231		if len(sessionIDs) == 0 {
232			return []string{}, []string{}, nil
233		}
234	
235		store, err := session.NewStateStore(ctx)
236		if err != nil {
237			return nil, nil, fmt.Errorf("failed to create state store: %w", err)
238		}
239	
240		for _, sessionID := range sessionIDs {
241			if err := store.Clear(ctx, sessionID); err != nil {
242				failed = append(failed, sessionID)
243			} else {
244				deleted = append(deleted, sessionID)
245			}
246		}
247	
248		return deleted, failed, nil
249	}
