251	// DeleteOrphanedCheckpoints removes checkpoint directories from the entire/checkpoints/v1 branch.
252	func DeleteOrphanedCheckpoints(ctx context.Context, checkpointIDs []string) (deleted []string, failed []string, err error) {
253		if len(checkpointIDs) == 0 {
254			return []string{}, []string{}, nil
255		}
256	
257		repo, err := OpenRepository(ctx)
258		if err != nil {
259			return nil, nil, fmt.Errorf("failed to open git repository: %w", err)
260		}
261	
262		// Get sessions branch
263		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
264		ref, err := repo.Reference(refName, true)
265		if err != nil {
266			return nil, nil, fmt.Errorf("sessions branch not found: %w", err)
267		}
268	
269		parentCommit, err := repo.CommitObject(ref.Hash())
270		if err != nil {
271			return nil, nil, fmt.Errorf("failed to get commit: %w", err)
272		}
273	
274		baseTree, err := parentCommit.Tree()
275		if err != nil {
276			return nil, nil, fmt.Errorf("failed to get tree: %w", err)
277		}
278	
279		// Flatten tree to entries
280		entries := make(map[string]object.TreeEntry)
281		if err := checkpoint.FlattenTree(repo, baseTree, "", entries); err != nil {
282			return nil, nil, fmt.Errorf("failed to flatten tree: %w", err)
283		}
284	
285		// Remove entries for each checkpoint
286		checkpointSet := make(map[string]bool)
287		for _, id := range checkpointIDs {
288			checkpointSet[id] = true
289		}
290	
291		// Find and remove entries matching checkpoint paths
292		for path := range entries {
293			for checkpointIDStr := range checkpointSet {
294				cpID, err := id.NewCheckpointID(checkpointIDStr)
295				if err != nil {
296					continue // Skip invalid checkpoint IDs
297				}
298				cpPath := cpID.Path()
299				if strings.HasPrefix(path, cpPath+"/") {
300					delete(entries, path)
301				}
302			}
303		}
304	
305		// Build new tree
306		newTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
307		if err != nil {
308			return nil, nil, fmt.Errorf("failed to build tree: %w", err)
309		}
310	
311		// Create commit
312		commit := &object.Commit{
313			Author: object.Signature{
314				Name:  "Entire CLI",
315				Email: "cli@entire.io",
316				When:  parentCommit.Author.When,
317			},
318			Committer: object.Signature{
319				Name:  "Entire CLI",
320				Email: "cli@entire.io",
321				When:  parentCommit.Committer.When,
322			},
323			Message:      fmt.Sprintf("Cleanup: removed %d orphaned checkpoints", len(checkpointIDs)),
324			TreeHash:     newTreeHash,
325			ParentHashes: []plumbing.Hash{ref.Hash()},
326		}
327	
328		obj := repo.Storer.NewEncodedObject()
329		if err := commit.Encode(obj); err != nil {
330			return nil, nil, fmt.Errorf("failed to encode commit: %w", err)
331		}
332	
333		commitHash, err := repo.Storer.SetEncodedObject(obj)
334		if err != nil {
335			return nil, nil, fmt.Errorf("failed to store commit: %w", err)
336		}
337	
338		// Update branch reference
339		newRef := plumbing.NewHashReference(refName, commitHash)
340		if err := repo.Storer.SetReference(newRef); err != nil {
341			return nil, nil, fmt.Errorf("failed to update branch: %w", err)
342		}
343	
344		// All checkpoints deleted successfully
345		return checkpointIDs, []string{}, nil
346	}
