354	// ListEligibleV2Generations returns archived checkpoints v2 /full/* generations
355	// eligible for deletion based on the configured retention window, along with
356	// warnings for malformed generations that were skipped.
357	func ListEligibleV2Generations(ctx context.Context, s *settings.EntireSettings) ([]CleanupItem, []string, error) {
358		repo, err := OpenRepository(ctx)
359		if err != nil {
360			return nil, nil, fmt.Errorf("failed to open git repository: %w", err)
361		}
362	
363		store := checkpoint.NewV2GitStore(repo, "origin")
364		candidates, tempRefs, warnings, err := listArchivedV2GenerationCandidates(ctx, repo, store)
365		if err != nil {
366			return nil, nil, fmt.Errorf("failed to list archived generations: %w", err)
367		}
368		defer removeTempRefs(repo, tempRefs)
369	
370		cutoff := time.Now().AddDate(0, 0, -s.GetFullTranscriptGenerationRetentionDays())
371		cleanupItems := make([]CleanupItem, 0, len(candidates))
372		generations := make([]cleanupGenerationState, 0, len(candidates))
373		metadataRefs := make([]plumbing.ReferenceName, 0, len(candidates))
374	
375		for _, candidate := range candidates {
376			commitHash, treeHash, refErr := store.GetRefState(candidate.RefName)
377			if refErr != nil {
378				warnings = append(warnings, fmt.Sprintf("generation %s: cannot read ref: %v", candidate.Name, refErr))
379				continue
380			}
381	
382			gen, foundCheckpointTimes, timestampErr := store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
383			if timestampErr != nil {
384				warnings = append(warnings, fmt.Sprintf("generation %s: failed to compute raw transcript timestamps: %v", candidate.Name, timestampErr))
385				continue
386			}
387			if !foundCheckpointTimes {
388				metadataRefs = append(metadataRefs, candidate.RefName)
389			}
390			generations = append(generations, cleanupGenerationState{
391				candidate:  candidate,
392				commitHash: commitHash,
393				gen:        gen,
394			})
395		}
396	
397		generationMetadata := readGenerationMetadataFiles(ctx, metadataRefs)
398		for _, generation := range generations {
399			gen := generation.gen
400			if metadata, ok := generationMetadata[generation.candidate.RefName]; ok {
401				if metadata.err != nil {
402					warnings = append(warnings, fmt.Sprintf("generation %s: failed to read generation.json: %v", generation.candidate.Name, metadata.err))
403					continue
404				}
405				if generationMetadataHasAnyTimestamp(metadata.gen) {
406					gen = metadata.gen
407				}
408			}
409	
410			hasOldest := !gen.OldestCheckpointAt.IsZero()
411			hasNewest := !gen.NewestCheckpointAt.IsZero()
412			switch {
413			case !hasOldest && !hasNewest:
414				warnings = append(warnings, fmt.Sprintf("generation %s: missing generation.json", generation.candidate.Name))
415				continue
416			case hasOldest != hasNewest:
417				warnings = append(warnings, fmt.Sprintf("generation %s: incomplete generation.json", generation.candidate.Name))
418				continue
419			case gen.OldestCheckpointAt.After(gen.NewestCheckpointAt):
420				warnings = append(warnings, fmt.Sprintf("generation %s: invalid timestamps", generation.candidate.Name))
421				continue
422			}
423			if !gen.NewestCheckpointAt.Before(cutoff) {
424				continue
425			}
426	
427			refOID := generation.candidate.RefOID
428			if refOID == "" {
429				refOID = generation.commitHash.String()
430			}
431			cleanupItems = append(cleanupItems, CleanupItem{
432				Type:   CleanupTypeV2Generation,
433				ID:     generation.candidate.Name,
434				RefOID: refOID,
435				Reason: "expired archived full transcript generation",
436			})
437		}
438	
439		return cleanupItems, warnings, nil
440	}
