458		specByRef := make(map[plumbing.ReferenceName]string, len(refNames))
459		for _, refName := range refNames {
460			spec := fmt.Sprintf("%s:%s", refName, paths.GenerationFileName)
461			specs = append(specs, spec)
462			specByRef[refName] = spec
463		}
