487	type archivedV2GenerationCandidate struct {
488		Name      string
489		RefName   plumbing.ReferenceName
490		RefOID    string
491		HasRemote bool
492	}
493	
494	func listArchivedV2GenerationCandidates(
495		ctx context.Context,
496		repo *git.Repository,
497		store *checkpoint.V2GitStore,
498	) ([]archivedV2GenerationCandidate, []plumbing.ReferenceName, []string, error) {
499		localNames, err := store.ListArchivedGenerations()
500		if err != nil {
501			return nil, nil, nil, fmt.Errorf("list local archived generations: %w", err)
502		}
503	
504		candidatesByName := make(map[string]archivedV2GenerationCandidate, len(localNames))
505		for _, name := range localNames {
506			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + name)
507			ref, refErr := repo.Reference(refName, true)
508			if refErr != nil {
509				continue
510			}
511			candidatesByName[name] = archivedV2GenerationCandidate{
512				Name:    name,
513				RefName: refName,
514				RefOID:  ref.Hash().String(),
515			}
516		}
517	
518		var warnings []string
519		var tempRefs []plumbing.ReferenceName
520		target, targetErr := remote.FetchURL(ctx)
521		if targetErr == nil && target != "" {
522			remoteRefs, remoteErr := listRemoteArchivedV2GenerationRefs(ctx, target)
523			if remoteErr != nil {
524				warnings = append(warnings, fmt.Sprintf("failed to list remote v2 generations: %v", remoteErr))
525			} else {
526				fetchTarget, fetchTargetErr := remote.ResolveFetchTarget(ctx, target)
527				if fetchTargetErr != nil {
528					warnings = append(warnings, fmt.Sprintf("failed to resolve remote for v2 generation fetch: %v", fetchTargetErr))
529				} else {
530					for name, remoteOID := range remoteRefs {
531						if candidate, ok := candidatesByName[name]; ok {
532							if candidate.RefOID == remoteOID {
533								candidate.HasRemote = true
534								candidatesByName[name] = candidate
535								continue
536							}
537							warnings = append(warnings, fmt.Sprintf("generation %s: local archived ref OID %s differs from remote OID %s; skipping cleanup", name, candidate.RefOID, remoteOID))
538							delete(candidatesByName, name)
539							continue
540						}
541						tempRef, fetchErr := fetchArchivedV2Generation(ctx, fetchTarget, name)
542						if fetchErr != nil {
543							warnings = append(warnings, fmt.Sprintf("generation %s: failed to fetch remote ref: %v", name, fetchErr))
544							continue
545						}
546						tempRefs = append(tempRefs, tempRef)
547						candidatesByName[name] = archivedV2GenerationCandidate{
548							Name:      name,
549							RefName:   tempRef,
550							RefOID:    remoteOID,
551							HasRemote: true,
552						}
553					}
554				}
555			}
556		}
557	
558		names := make([]string, 0, len(candidatesByName))
559		for name := range candidatesByName {
560			names = append(names, name)
561		}
562		sort.Strings(names)
563	
564		candidates := make([]archivedV2GenerationCandidate, 0, len(names))
565		for _, name := range names {
566			candidates = append(candidates, candidatesByName[name])
567		}
568		return candidates, tempRefs, warnings, nil
569	}
570	
571	func listRemoteArchivedV2GenerationRefs(ctx context.Context, target string) (map[string]string, error) {
572		output, err := remote.LsRemote(ctx, target, paths.V2FullRefPrefix+"*")
573		if err != nil {
574			return nil, fmt.Errorf("ls remote v2 generations: %w", err)
575		}
576	
577		refs := make(map[string]string)
578		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
579			if line == "" {
580				continue
581			}
582			parts := strings.Fields(line)
583			if len(parts) < 2 {
584				continue
585			}
586			refName := parts[1]
587			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
588			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
589				continue
590			}
591			refs[suffix] = parts[0]
592		}
593		return refs, nil
594	}
595	
596	func fetchArchivedV2Generation(ctx context.Context, fetchTarget, name string) (plumbing.ReferenceName, error) {
597		refName := paths.V2FullRefPrefix + name
598		tempRef := plumbing.ReferenceName("refs/entire-clean-tmp/v2/full/" + name)
599		refSpec := fmt.Sprintf("+%s:%s", refName, tempRef)
600		if output, err := remote.Fetch(ctx, remote.FetchOptions{
601			Remote:   fetchTarget,
602			RefSpecs: []string{refSpec},
603			NoTags:   true,
604			NoFilter: true,
605		}); err != nil {
606			return "", fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
607		}
608		return tempRef, nil
609	}
610	
611	func removeTempRefs(repo *git.Repository, refs []plumbing.ReferenceName) {
612		for _, ref := range refs {
613			_ = repo.Storer.RemoveReference(ref) //nolint:errcheck // cleanup is best-effort
614		}
615	}
616	
617	// V2GenerationRef pairs a generation name with the OID observed at listing time.
618	type V2GenerationRef struct {
619		Name   string
620		RefOID string // Commit hash for compare-and-swap; empty skips the check
621	}
622	
623	// DeleteV2Generations deletes archived checkpoints v2 /full/* generation refs.
624	// When RefOID is set, deletion uses compare-and-swap to avoid deleting a ref
625	// that was repointed after enumeration.
626	func DeleteV2Generations(ctx context.Context, generations []V2GenerationRef) (deleted []string, failed []string, err error) { //nolint:unparam // err kept for consistency with other Delete* functions
627		if len(generations) == 0 {
628			return []string{}, []string{}, nil
629		}
630	
631		pushTarget, _, pushTargetErr := remote.PushURL(ctx, "origin")
632	
633		for _, gen := range generations {
634			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + gen.Name)
635			localErr := DeleteRefCLI(ctx, refName.String(), gen.RefOID)
636			if errors.Is(localErr, ErrRefNotFound) {
637				localErr = nil
638			}
639			if localErr != nil {
640				failed = append(failed, gen.Name)
641				continue
642			}
643			if pushTargetErr == nil && pushTarget != "" {
644				if remoteErr := deleteRemoteRef(ctx, pushTarget, refName.String(), gen.RefOID); remoteErr != nil {
645					failed = append(failed, gen.Name)
646					continue
647				}
648			}
649			deleted = append(deleted, gen.Name)
650		}
651	
652		return deleted, failed, nil
653	}
654	
655	func deleteRemoteRef(ctx context.Context, target, refName, expectedOID string) error {
656		return pushWithLease(ctx, target, ":"+refName, refName, expectedOID,
657			"delete remote ref "+refName)
658	}
659	
660	// pushWithLease runs `git push <target> <refSpec>` with an optional
661	// `--force-with-lease=<leaseRef>:<expectedOID>` guard. errCtx prefixes the
662	// error message when no stderr output is available from the push.
663	func pushWithLease(ctx context.Context, target, refSpec, leaseRef, expectedOID, errCtx string) error {
664		extraArgs := []string{}
665		if expectedOID != "" {
666			extraArgs = append(extraArgs, fmt.Sprintf("--force-with-lease=%s:%s", leaseRef, expectedOID))
667		}
668		result, err := remote.PushWithOptions(ctx, remote.PushOptions{
669			Remote:    target,
670			RefSpecs:  []string{refSpec},
671			ExtraArgs: extraArgs,
672		})
673		if err != nil {
674			output := strings.TrimSpace(result.Output)
675			if output != "" {
676				return fmt.Errorf("%s: %w", output, err)
677			}
678			return fmt.Errorf("%s: %w", errCtx, err)
679		}
680		return nil
681	}
682	
683	// ListAllItems returns all Entire items for full cleanup.
684	// This includes all shadow branches and all session states regardless of
685	// whether they have checkpoints or active shadow branches.
686	func ListAllItems(ctx context.Context) ([]CleanupItem, error) {
687		var cleanupItems []CleanupItem
688	
689		// All shadow branches (using ListShadowBranches directly, not
690		// ListOrphanedItems, so this won't break if orphan filtering is added)
691		branches, err := ListShadowBranches(ctx)
692		if err != nil {
693			return nil, fmt.Errorf("listing shadow branches: %w", err)
694		}
695		for _, branch := range branches {
696			cleanupItems = append(cleanupItems, CleanupItem{
697				Type:   CleanupTypeShadowBranch,
698				ID:     branch,
699				Reason: "clean all",
700			})
701		}
702	
703		// All session states (not just orphaned)
704		store, err := session.NewStateStore(ctx)
705		if err != nil {
706			return nil, fmt.Errorf("failed to create state store: %w", err)
707		}
708	
709		states, err := store.List(ctx)
710		if err != nil {
711			return nil, fmt.Errorf("failed to list session states: %w", err)
712		}
713	
714		for _, state := range states {
715			cleanupItems = append(cleanupItems, CleanupItem{
716				Type:   CleanupTypeSessionState,
717				ID:     state.SessionID,
718				Reason: "clean all",
719			})
720		}
721	
722		return cleanupItems, nil
723	}
724	
725	// DeleteAllCleanupItems deletes all specified cleanup items.
726	// Logs each deletion for audit purposes.
727	func DeleteAllCleanupItems(ctx context.Context, items []CleanupItem) (*CleanupResult, error) {
728		result := &CleanupResult{}
729		logCtx := logging.WithComponent(ctx, "cleanup")
730	
731		// Build ID-to-Reason map for logging after deletion
732		reasonMap := make(map[string]string)
733		for _, item := range items {
734			reasonMap[item.ID] = item.Reason
735		}
736	
737		// Group items by type
738		var branches, states, checkpoints []string
739		var v2Generations []V2GenerationRef
740		for _, item := range items {
741			switch item.Type {
742			case CleanupTypeShadowBranch:
743				branches = append(branches, item.ID)
744			case CleanupTypeSessionState:
745				states = append(states, item.ID)
746			case CleanupTypeCheckpoint:
747				checkpoints = append(checkpoints, item.ID)
748			case CleanupTypeV2Generation:
749				v2Generations = append(v2Generations, V2GenerationRef{Name: item.ID, RefOID: item.RefOID})
750			}
751		}
752	
753		// Delete shadow branches
754		if len(branches) > 0 {
755			deleted, failed, err := DeleteShadowBranches(ctx, branches)
756			if err != nil {
757				return result, err
758			}
759			result.ShadowBranches = deleted
760			result.FailedBranches = failed
761	
762			// Log deleted branches
763			for _, id := range deleted {
764				logging.Info(logCtx, "deleted shadow branch",
765					slog.String("type", string(CleanupTypeShadowBranch)),
766					slog.String("id", id),
767					slog.String("reason", reasonMap[id]),
768				)
769			}
770			// Log failed branches
771			for _, id := range failed {
772				logging.Warn(logCtx, "failed to delete shadow branch",
773					slog.String("type", string(CleanupTypeShadowBranch)),
774					slog.String("id", id),
775					slog.String("reason", reasonMap[id]),
776				)
777			}
778		}
779	
780		// Delete session states
781		if len(states) > 0 {
782			deleted, failed, err := DeleteOrphanedSessionStates(ctx, states)
783			if err != nil {
784				return result, err
785			}
786			result.SessionStates = deleted
787			result.FailedStates = failed
788	
789			// Log deleted session states
790			for _, id := range deleted {
791				logging.Info(logCtx, "deleted session state",
792					slog.String("type", string(CleanupTypeSessionState)),
793					slog.String("id", id),
794					slog.String("reason", reasonMap[id]),
795				)
796			}
797			// Log failed session states
798			for _, id := range failed {
799				logging.Warn(logCtx, "failed to delete session state",
800					slog.String("type", string(CleanupTypeSessionState)),
801					slog.String("id", id),
802					slog.String("reason", reasonMap[id]),
803				)
804			}
805		}
806	
807		// Delete checkpoints
808		if len(checkpoints) > 0 {
809			deleted, failed, err := DeleteOrphanedCheckpoints(ctx, checkpoints)
810			if err != nil {
811				return result, err
812			}
813			result.Checkpoints = deleted
814			result.FailedCheckpoints = failed
815	
816			// Log deleted checkpoints
817			for _, id := range deleted {
818				logging.Info(logCtx, "deleted checkpoint",
819					slog.String("type", string(CleanupTypeCheckpoint)),
820					slog.String("id", id),
821					slog.String("reason", reasonMap[id]),
822				)
823			}
824			// Log failed checkpoints
825			for _, id := range failed {
826				logging.Warn(logCtx, "failed to delete checkpoint",
827					slog.String("type", string(CleanupTypeCheckpoint)),
828					slog.String("id", id),
829					slog.String("reason", reasonMap[id]),
830				)
831			}
832		}
833	
834		if len(v2Generations) > 0 {
835			deleted, failed, err := DeleteV2Generations(ctx, v2Generations)
836			if err != nil {
837				return result, err
838			}
839			result.V2Generations = deleted
840			result.FailedV2Refs = failed
841	
842			for _, id := range deleted {
843				logging.Info(logCtx, "deleted v2 generation",
844					slog.String("type", string(CleanupTypeV2Generation)),
845					slog.String("id", id),
846					slog.String("reason", reasonMap[id]),
847				)
848			}
849			for _, id := range failed {
850				logging.Warn(logCtx, "failed to delete v2 generation",
851					slog.String("type", string(CleanupTypeV2Generation)),
852					slog.String("id", id),
853					slog.String("reason", reasonMap[id]),
854				)
855			}
856		}
857	
858		// Log summary
859		totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints) + len(result.V2Generations)
860		totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints) + len(result.FailedV2Refs)
861		if totalDeleted > 0 || totalFailed > 0 {
862			logging.Info(logCtx, "cleanup completed",
863				slog.Int("deleted_branches", len(result.ShadowBranches)),
864				slog.Int("deleted_session_states", len(result.SessionStates)),
865				slog.Int("deleted_checkpoints", len(result.Checkpoints)),
866				slog.Int("deleted_v2_generations", len(result.V2Generations)),
867				slog.Int("failed_branches", len(result.FailedBranches)),
868				slog.Int("failed_session_states", len(result.FailedStates)),
869				slog.Int("failed_checkpoints", len(result.FailedCheckpoints)),
870				slog.Int("failed_v2_generations", len(result.FailedV2Refs)),
871			)
872		}
873	
874		return result, nil
875	}
